def caption(index, number, name):
    topic, text = TEMAS[(index * 4 + number) % len(TEMAS)]
    closing = ['¿Qué detalle te llamó la atención?', 'Puedes seguir la conversación en los comentarios.', 'Visita el perfil para recorrer otros ejemplos.', 'Guarda esta idea para explorar la ficha relacionada.'][index // 13]
    return f'[DEMOSTRACIÓN] {text} {closing} — {name}. #{topic}'
